#include <print>

int main() {
    int n = 1;
    int sum = 0;

    while (sum <= 10) {
        sum += n;
        std::println("加上 {} 后 sum = {}", n, sum);
        n++;
    }

    std::println("总数 {} 一共跑了 {} 圈", sum, n - 1);
    // 把 n++ 删掉再跑，屏幕刷不停，只能 Ctrl+C

    return 0;
}

